import './index.less'

export default class PhotovolaticProduct {
    constructor() {
        this.targetDOMs = document.querySelectorAll('[data-product-link]')
        this.viewMoreBtn = document.querySelector('[data-product-view-more]')

        if (!!this.targetDOMs.length && this.viewMoreBtn) {
            this.init()
        }
    }
    init() {
        this.targetDOMs.forEach(item => {
            item.onclick = (e) => {
                const { productTitle, productHref, productButtonText } = e.target.dataset
                this.GAEvent({
                    position: productTitle,
                    button_name: productButtonText,
                    link: productHref,
                })
            }
        })

        this.viewMoreBtn.onclick = e => {
            const { viewMoreHref, viewMoreButtonText } = e.target.dataset
            this.GAEvent({
                button_name: viewMoreButtonText,
                link: viewMoreHref,
            })
        }
    }

    // 数据埋码
    GAEvent(params) {
        window.dataLayer.push({ "event_parameters": null });
        window.dataLayer.push({
            "event":"ga4Event",
            "event_name":"photovoltaics_user_clicks",
            "event_parameters":{
                "current_page": window.location.href, // current page url
                "module": "Product Display",
                ...params
            }
        });
    }
}
