/**
 * 光伏轮播组件
 */
export function PhotovolaticVat(){
    $(() => {
        const $photovolaticVAT = $('.photovolatic-vat-component');
        if($photovolaticVAT.length > 0){
            $photovolaticVAT.each(function(index){
                $(this).addClass(`photovolatic-vat-component-${index + 1}`);
                const $currSwiper = $(this).find('.photovolatic-box');

                // 轮播图张数
                const total = $currSwiper.data('total') || 0;
                if (total <= 1) {
                    return;
                }

                new Swiper(`.photovolatic-vat-component-${index + 1} .photovolatic-box`, {
                    navigation: {
                        nextEl: `.photovolatic-vat-component-${index + 1} .swiper-button-next`,
                        prevEl: `.photovolatic-vat-component-${index + 1} .swiper-button-prev`,
                    },
                    effect: 'slide',
                    loop: true
                });
            })
        }
    })
}
