/**
 * 周年KV组件
 * PC端增加滚动监听动效（依赖 GSAP + ScrollTrigger实现）
 */
export function AnniversaryKVComponent() {
    $(function () {
        const $anniversaryKv = $('.anniversary-kv-box');
        if ($anniversaryKv.length === 0 || window.innerWidth < 1024) {
            return;
        }
        // 是否为Shopify2.0版本
        const isShopify2 = $('body').hasClass('theme-v2');

        window.gsap.registerPlugin(window.ScrollTrigger);
        let tl;

        function activeScrollEffect(){

            // 启用动效开关
            if ($anniversaryKv.data('enable-effect')) {
                const $siteHeader = $('.site-header') || $('jky-header') || $('header-v5');
                const boxH = $anniversaryKv.height();
                const rBoxH = window.innerWidth * 0.4624;
                if(boxH > rBoxH){
                    $anniversaryKv.css('height',`46.24vw`)
                }

                let currHeaderH;
                if (isShopify2) {
                    const localeSwitcherH = $('#shopify-section-locale-switcher .locale-switcher').outerHeight() || 0;
                    const announcementH = $('#shopify-section-header .announcement').outerHeight() || 0;
                    const themeV2HeaderH = $('.theme-v2-header').outerHeight();
                    currHeaderH = localeSwitcherH + announcementH + themeV2HeaderH;
                } else {
                    currHeaderH = $siteHeader.outerHeight();
                }
                const startVal = `-${currHeaderH}px`;

                // 储存实例动画已经进行了多长的时间
                const time = tl ? tl.time() : 0;
                if(tl){
                    tl.kill();
                }

                tl = window.gsap.timeline({
                    scrollTrigger: {
                        trigger: ".anniversary-kv-box",
                        pin: true, // pin the trigger element while active
                        start: startVal, // when the top of the trigger hits the top of the viewport
                        end: "+=1200", // end after scrolling 500px beyond the start
                        scrub: 1, // smooth scrubbing, takes 1 second to "catch up" to the scrollbar
                        snap: {
                            snapTo: "labels", // snap to the closest label in the timeline
                            duration: {
                                min: 0.2,
                                max: 3
                            }, // the snap animation should be at least 0.2 seconds, but no more than 3 seconds (determined by velocity)
                            delay: 0, // wait 0.2 seconds from the last scroll event before doing the snapping
                            ease: "power3.inOut", // the ease of the snap animation ("power3" by default)
                        },
                        onToggle: (self) => {
                            if (self.isActive) {
                                $(".anniversary-kv-box picture source").each(function () {
                                    const imgSrc = $(this).data('srcset');
                                    $(this).attr('srcset', imgSrc)
                                })
                            }
                        }
                    }
                });

                // add animations and labels to the timeline
                tl.addLabel("start")
                    // 天空 缩放点在 左上
                    .to(".kv-sky", {
                        scale: 1,
                        transformOrigin: "left top"
                    }, "<")

                    // 地面 缩放点在 左上
                    .to(".kv-ground", {
                        scale: 1,
                        opacity: 1,
                        transformOrigin: "left top"
                    }, "<")

                    // 文字 缩放点在 左右居中 顶部35%
                    .to(".kv-text", {
                        scale: 0.63,
                        transformOrigin: "50% 35%"
                    }, "<")

                    // 人物 缩放点在右上
                    .to(".kv-people", {
                        scale: 1,
                        opacity: 1,
                        transformOrigin: "right top",
                    }, "<")

                    // 信任状 快结束时出现
                    .addLabel("credential")
                    .to(".credential-box", { opacity: 1 })
                    .addLabel("end");

                tl.time(time);
            }
        }
        activeScrollEffect()
    })
}
